/**
 * Server-side truth and formatting guards for AI bullet rewriting.
 * Enforces strict non-hallucination of numerical metrics and word length constraints.
 */

/**
 * Extracts all digit sequences and verifies that every digit sequence and character
 * in the generated variant text is legitimately derived from rawText or userFacts.
 * Missing metrics must use bracketed placeholders (e.g. [X%]) which contain no digits.
 *
 * @param rawText - The original bullet text input by the user.
 * @param variantText - The candidate rewritten bullet text generated by the model.
 * @param userFacts - Optional additional user-supplied facts or figures.
 * @returns true if zero fabricated digits are detected; false otherwise.
 */
export function verifyZeroInventedDigits(
  rawText: string,
  variantText: string,
  userFacts?: string
): boolean {
  // Extract all digit sequences (\d+) from candidate variant
  const variantDigitSeqs = variantText.match(/\d+/g);
  if (!variantDigitSeqs || variantDigitSeqs.length === 0) {
    // If the variant contains no digits (e.g. only text and [X%] placeholders), it passes
    return true;
  }

  const combinedSource = `${rawText} ${userFacts || ''}`;
  const sourceDigitChars = new Set(combinedSource.match(/\d/g) || []);
  const sourceDigitSeqs = combinedSource.match(/\d+/g) || [];

  // Check 1: Every individual digit character in variant must exist in source
  const variantDigitChars = variantText.match(/\d/g) || [];
  for (const char of variantDigitChars) {
    if (!sourceDigitChars.has(char)) {
      return false;
    }
  }

  // Check 2: Every digit sequence in variant must exist in source
  // Account for comma-formatted numbers like 1,000 vs 1000
  const sourceSeqSet = new Set(sourceDigitSeqs);
  const normalizedSource = combinedSource.replace(/,/g, '');
  const normalizedSourceSeqs = new Set(normalizedSource.match(/\d+/g) || []);

  for (const seq of variantDigitSeqs) {
    if (!sourceSeqSet.has(seq) && !normalizedSourceSeqs.has(seq)) {
      return false;
    }
  }

  return true;
}

/**
 * Verifies that the word count of the bullet text falls within acceptable boundaries.
 * Blueprint Section 6.3 mandates bullets between 12 and 32 words.
 *
 * @param text - The bullet text to count words for.
 * @param min - Minimum allowed words (default: 12).
 * @param max - Maximum allowed words (default: 32).
 * @returns true if word count is within [min, max]; false otherwise.
 */
export function verifyWordCount(
  text: string,
  min: number = 12,
  max: number = 32
): boolean {
  const trimmed = text.trim();
  if (!trimmed) {
    return false;
  }
  const words = trimmed.split(/\s+/).filter(Boolean);
  return words.length >= min && words.length <= max;
}
